package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"regexp"
	"strings"

	"golang.org/x/tools/go/packages"
)

type ignoredFunction struct {
	pkg    string
	name   string
	argTyp string
}

type Checker struct {
	ignoreTests      bool
	ignoreGenerated  bool
	ignoreRx         map[string]*regexp.Regexp
	ignorePackages   map[string]bool
	blank            bool
	asserts          bool
	abspath          bool
	verbose          bool
	exclude          map[string]bool
	excludeOnly      bool
	stdExcludes      map[string]bool
	fset             *token.FileSet
	typeInfo         types.Info
}

func NewChecker(ignoreTests, ignoreGenerated, blank, asserts, abspath, verbose, excludeOnly bool) *Checker {
	return &Checker{
		ignoreTests:     ignoreTests,
		ignoreGenerated: ignoreGenerated,
		blank:           blank,
		asserts:         asserts,
		abspath:         abspath,
		verbose:         verbose,
		exclude:         make(map[string]bool),
		excludeOnly:     excludeOnly,
		ignoreRx:        make(map[string]*regexp.Regexp),
		ignorePackages:  make(map[string]bool),
		stdExcludes:     getStdExcludes(),
		fset:            token.NewFileSet(),
		typeInfo: types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Defs:       make(map[*ast.Ident]types.Object),
			Uses:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		},
	}
}

func getStdExcludes() map[string]bool {
	// Standard library functions that never return errors or ignore them
	return map[string]bool{
		"fmt.Print":        true,
		"fmt.Println":      true,
		"fmt.Printf":       true,
		"fmt.Fprint":       true,
		"fmt.Fprintln":     true,
		"fmt.Fprintf":      true,
		"fmt.Sprint":       true,
		"fmt.Sprintln":     true,
		"fmt.Sprintf":      true,
		"bytes.Buffer.Write":       true,
		"bytes.Buffer.WriteString": true,
		"bytes.Buffer.WriteRune":   true,
		"bytes.Buffer.WriteByte":   true,
		"strings.Builder.Write":       true,
		"strings.Builder.WriteString": true,
		"strings.Builder.WriteRune":   true,
		"strings.Builder.WriteByte":   true,
	}
}

func (c *Checker) addIgnorePattern(pkg string, pattern string) error {
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return err
	}
	c.ignoreRx[pkg] = rx
	return nil
}

func (c *Checker) addIgnorePackage(pkg string) {
	c.ignorePackages[pkg] = true
}

func (c *Checker) addExclude(name string) {
	c.exclude[name] = true
}

func (c *Checker) Check(pkg *packages.Package) ([]string, error) {
	if c.verbose {
		fmt.Printf("checking %s\n", pkg.Name)
	}

	var issues []string
	var nodeIssues []nodeIssue

	for _, f := range pkg.Syntax {
		if c.ignoreTests && strings.HasSuffix(c.fset.Position(f.Pos()).Filename, "_test.go") {
			continue
		}

		if c.ignoreGenerated && isGeneratedFile(f) {
			continue
		}

		visitor := &astVisitor{
			checker: c,
			pkg:     pkg,
			issues:  &nodeIssues,
		}
		ast.Walk(visitor, f)
	}

	// Sort and format issues
	for _, issue := range nodeIssues {
		pos := pkg.Fset.Position(issue.node.Pos())
		if c.abspath {
			issues = append(issues, fmt.Sprintf("%s:%d:%d:\t%s(%s)", pos.Filename, pos.Line, pos.Column, issue.funcName, issue.call))
		} else {
			// Make path relative
			issues = append(issues, fmt.Sprintf("%s:%d:%d:\t%s(%s)", pos.Filename, pos.Line, pos.Column, issue.funcName, issue.call))
		}
	}

	return issues, nil
}

type nodeIssue struct {
	node     ast.Node
	funcName string
	call     string
}

type astVisitor struct {
	checker *Checker
	pkg     *packages.Package
	issues  *[]nodeIssue
}

func (v *astVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return v
	}

	switch n := node.(type) {
	case *ast.ExprStmt:
		if v.checkExprStmt(n) {
			*v.issues = append(*v.issues, nodeIssue{
				node:     n,
				funcName: v.getFuncName(n.X),
				call:     v.getCallString(n.X),
			})
		}

	case *ast.AssignStmt:
		if v.checker.blank && n.Tok == token.ASSIGN {
			for _, lhs := range n.Lhs {
				if id, ok := lhs.(*ast.Ident); ok && id.Name == "_" {
					if v.isErrorReturningCall(n.Rhs[len(n.Rhs)-1]) {
						*v.issues = append(*v.issues, nodeIssue{
							node:     n,
							funcName: v.getFuncName(n.Rhs[len(n.Rhs)-1]),
							call:     v.getCallString(n.Rhs[len(n.Rhs)-1]),
						})
					}
				}
			}
		}

	case *ast.TypeAssertExpr:
		if v.checker.asserts && n.Type != nil {
			*v.issues = append(*v.issues, nodeIssue{
				node:     n,
				funcName: v.getTypeAssertName(n),
				call:     v.getTypeAssertString(n),
			})
		}
	}

	return v
}

func (v *astVisitor) checkExprStmt(stmt *ast.ExprStmt) bool {
	return v.isErrorReturningCall(stmt.X)
}

func (v *astVisitor) isErrorReturningCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}

	// Check if this should be ignored
	funcName := v.getFuncName(call)
	if v.checker.isIgnored(funcName) {
		return false
	}

	// Check the return type
	return v.hasErrorReturn(call)
}

func (v *astVisitor) hasErrorReturn(call *ast.CallExpr) bool {
	// Try to get type information
	if v.checker.verbose {
		funcName := v.getFuncName(call)
		fmt.Printf("  %s\t%s\n", funcName, v.getCallString(call))
	}
	return true
}

func (v *astVisitor) getFuncName(node ast.Node) string {
	switch n := node.(type) {
	case *ast.CallExpr:
		return v.getFuncName(n.Fun)
	case *ast.SelectorExpr:
		if ident, ok := n.X.(*ast.Ident); ok {
			return ident.Name + "." + n.Sel.Name
		}
		return "unknown"
	case *ast.Ident:
		return n.Name
	}
	return "unknown"
}

func (v *astVisitor) getCallString(node ast.Node) string {
	switch n := node.(type) {
	case *ast.CallExpr:
		return v.getCallString(n.Fun)
	case *ast.SelectorExpr:
		if ident, ok := n.X.(*ast.Ident); ok {
			return ident.Name + "." + n.Sel.Name
		}
		return "unknown"
	case *ast.Ident:
		return n.Name
	}
	return "unknown"
}

func (v *astVisitor) getTypeAssertName(node *ast.TypeAssertExpr) string {
	return v.getFuncName(node)
}

func (v *astVisitor) getTypeAssertString(node *ast.TypeAssertExpr) string {
	return "type assert"
}

func (c *Checker) isIgnored(name string) bool {
	// Check if in exclude list
	if c.exclude[name] {
		return true
	}

	// Check if excluded via standard excludes
	if !c.excludeOnly && c.stdExcludes[name] {
		return true
	}

	// Check package ignore patterns
	parts := strings.Split(name, ".")
	if len(parts) > 0 {
		pkg := parts[0]
		if c.ignorePackages[pkg] {
			return true
		}

		if rx, ok := c.ignoreRx[pkg]; ok && rx.MatchString(name) {
			return true
		}
	}

	return false
}

func isGeneratedFile(f *ast.File) bool {
	for _, comment := range f.Comments {
		for _, c := range comment.List {
			if strings.Contains(c.Text, "Code generated") && strings.Contains(c.Text, "DO NOT EDIT") {
				return true
			}
		}
	}
	return false
}

type Walk func(ast.Node) ast.Visitor

func (w Walk) Visit(node ast.Node) ast.Visitor {
	return w(node)
}

func (v *astVisitor) Visit(node ast.Node) ast.Visitor {
	// Will be overridden
	return v
}
EOF

