package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
	"golang.org/x/tools/go/types/typeutil"
)

type Checker struct {
	ignoreTests      bool
	ignoreGenerated  bool
	ignoreRx         map[string]*regexp.Regexp
	ignorePackages   map[string]bool
	blank            bool
	asserts          bool
	abspath          bool
	verbose          bool
	exclude          map[string]bool
	excludeOnly      bool
	stdExcludes      map[string]bool
}

func NewChecker(ignoreTests, ignoreGenerated, blank, asserts, abspath, verbose, excludeOnly bool) *Checker {
	return &Checker{
		ignoreTests:     ignoreTests,
		ignoreGenerated: ignoreGenerated,
		blank:           blank,
		asserts:         asserts,
		abspath:         abspath,
		verbose:         verbose,
		exclude:         make(map[string]bool),
		excludeOnly:     excludeOnly,
		ignoreRx:        make(map[string]*regexp.Regexp),
		ignorePackages:  make(map[string]bool),
		stdExcludes:     getStdExcludes(),
	}
}

func getStdExcludes() map[string]bool {
	// Standard library functions whose error returns can be safely ignored
	return map[string]bool{
		"fmt.Print":        true,
		"fmt.Println":      true,
		"fmt.Printf":       true,
		"fmt.Fprint":       true,
		"fmt.Fprintln":     true,
		"fmt.Fprintf":      true,
		"fmt.Sprint":       true,
		"fmt.Sprintln":     true,
		"fmt.Sprintf":      true,
	}
}

func (c *Checker) AddIgnorePattern(pkg string, pattern string) error {
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return err
	}
	c.ignoreRx[pkg] = rx
	return nil
}

func (c *Checker) AddIgnorePackage(pkg string) {
	c.ignorePackages[pkg] = true
}

func (c *Checker) AddExclude(name string) {
	c.exclude[name] = true
}

func (c *Checker) LoadExcludes(filename string) error {
	file, err := os.Open(filename)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		// Skip empty lines and comments
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		c.AddExclude(line)
	}
	return scanner.Err()
}

func (c *Checker) CheckPackages(patterns []string, tags map[string]bool) ([]string, error) {
	cfg := &packages.Config{
		Mode: packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo,
	}

	if len(tags) > 0 {
		var tagList []string
		for tag := range tags {
			tagList = append(tagList, tag)
		}
		cfg.BuildFlags = []string{"-tags", strings.Join(tagList, ",")}
	}

	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		return nil, err
	}

	var issues []string
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			errStr := ""
			for _, perr := range pkg.Errors {
				errStr += perr.Error() + "; "
			}
			return nil, fmt.Errorf("errors while loading package %s: %s", pkg.PkgPath, errStr)
		}

		pkgIssues := c.checkPackage(pkg)
		issues = append(issues, pkgIssues...)
	}

	sort.Strings(issues)
	return issues, nil
}

func (c *Checker) checkPackage(pkg *packages.Package) []string {
	if c.verbose {
		fmt.Printf("checking %s\n", pkg.Name)
	}

	var issues []string

	for _, file := range pkg.Syntax {
		filename := pkg.Fset.Position(file.Pos()).Filename

		// Check if we should ignore this file
		if c.ignoreTests && strings.HasSuffix(filename, "_test.go") {
			continue
		}

		if c.ignoreGenerated && isGeneratedFile(file) {
			continue
		}

		fileIssues := c.checkFile(file, pkg, filename)
		issues = append(issues, fileIssues...)
	}

	return issues
}

func (c *Checker) checkFile(file *ast.File, pkg *packages.Package, filename string) []string {
	var issues []string

	visitor := &fileVisitor{
		checker:  c,
		pkg:      pkg,
		file:     file,
		filename: filename,
		issues:   &issues,
	}
	ast.Walk(visitor, file)

	return issues
}

type fileVisitor struct {
	checker  *Checker
	pkg      *packages.Package
	file     *ast.File
	filename string
	issues   *[]string
}

func (v *fileVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return v
	}

	switch n := node.(type) {
	case *ast.ExprStmt:
		v.checkExprStmt(n)
	case *ast.AssignStmt:
		v.checkAssignStmt(n)
	}

	return v
}

func (v *fileVisitor) checkExprStmt(stmt *ast.ExprStmt) {
	call, ok := stmt.X.(*ast.CallExpr)
	if !ok {
		return
	}

	funcName := v.getFuncName(call.Fun)
	if v.isIgnored(funcName) {
		return
	}

	if v.hasErrorReturn(call) {
		if v.checker.verbose {
			fmt.Printf("  %s\t%s\n", funcName, v.getCallString(stmt.X))
		}

		issue := v.formatIssue(stmt.Pos(), funcName, v.getCallString(stmt.X))
		*v.issues = append(*v.issues, issue)
	}
}

func (v *fileVisitor) checkAssignStmt(stmt *ast.AssignStmt) {
	if !v.checker.blank || stmt.Tok != token.ASSIGN {
		return
	}

	// Check for assignments to blank identifier
	for i, lhs := range stmt.Lhs {
		if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
			if i < len(stmt.Rhs) {
				if v.isErrorReturningCall(stmt.Rhs[i]) {
					issue := v.formatIssue(stmt.Pos(), v.getFuncName(stmt.Rhs[i]), v.getCallString(stmt.Rhs[i]))
					*v.issues = append(*v.issues, issue)
				}
			}
		}
	}
}

func (v *fileVisitor) isErrorReturningCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	return v.hasErrorReturn(call)
}

func (v *fileVisitor) hasErrorReturn(call *ast.CallExpr) bool {
	// Get the function type
	callType := v.pkg.TypesInfo.TypeOf(call.Fun)
	if callType == nil {
		return false
	}

	var sig *types.Signature
	switch t := callType.(type) {
	case *types.Signature:
		sig = t
	case *types.Named:
		if s, ok := t.Underlying().(*types.Signature); ok {
			sig = s
		}
	}

	if sig == nil || sig.Results() == nil || sig.Results().Len() == 0 {
		return false
	}

	// Check if last return type is error
	lastResult := sig.Results().At(sig.Results().Len() - 1)
	return isErrorType(lastResult.Type())
}

func isErrorType(t types.Type) bool {
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Pkg() == nil && named.Obj().Name() == "error"
	}
	return false
}

func (v *fileVisitor) isIgnored(funcName string) bool {
	checker := v.checker

	// Check if in exclude list
	if checker.exclude[funcName] {
		return true
	}

	// Check if excluded via standard excludes (unless excludeonly)
	if !checker.excludeOnly && checker.stdExcludes[funcName] {
		return true
	}

	// Check package ignore patterns
	parts := strings.Split(funcName, ".")
	if len(parts) > 0 {
		pkg := parts[0]
		if checker.ignorePackages[pkg] {
			return true
		}

		if rx, ok := checker.ignoreRx[pkg]; ok {
			if rx.MatchString(funcName) {
				return true
			}
		}

		// Also check default ignore patterns
		if !checker.excludeOnly {
			if rx, ok := checker.ignoreRx[""]; ok {
				if rx.MatchString(funcName) {
					return true
				}
			}
		}
	}

	return false
}

func (v *fileVisitor) getFuncName(expr ast.Expr) string {
	switch n := expr.(type) {
	case *ast.SelectorExpr:
		return v.getFuncName(n.X) + "." + n.Sel.Name
	case *ast.Ident:
		return n.Name
	default:
		return "unknown"
	}
}

func (v *fileVisitor) getCallString(expr ast.Expr) string {
	switch n := expr.(type) {
	case *ast.CallExpr:
		return v.getFuncName(n.Fun)
	case *ast.SelectorExpr:
		return v.getFuncName(n.X) + "." + n.Sel.Name
	case *ast.Ident:
		return n.Name
	default:
		return "unknown"
	}
}

func (v *fileVisitor) formatIssue(pos token.Pos, funcName, callStr string) string {
	posInfo := v.pkg.Fset.Position(pos)
	filename := posInfo.Filename

	if !v.checker.abspath {
		if rel, err := filepath.Rel(".", filename); err == nil {
			filename = rel
		}
	}

	return fmt.Sprintf("%s:%d:%d:\t%s(%s)", filename, posInfo.Line, posInfo.Column, funcName, callStr)
}

func isGeneratedFile(file *ast.File) bool {
	for _, commentGroup := range file.Comments {
		for _, comment := range commentGroup.List {
			text := comment.Text
			if strings.Contains(text, "Code generated") && strings.Contains(text, "DO NOT EDIT") {
				return true
			}
		}
	}
	return false
}

// Walk is a helper to walk AST nodes
type Walk func(ast.Node) ast.Visitor

func (w Walk) Visit(node ast.Node) ast.Visitor {
	return w(node)
}

// Walk walks the AST nodes
func Walk(v ast.Visitor, node ast.Node) {
	ast.Walk(v, node)
}

// Make sure we implement ast.Visitor properly
var _ ast.Visitor = (*fileVisitor)(nil)
