		os.Setenv("GOFLAGS", fmt.Sprintf("-mod=%s", mod))
	}

	// Get packages to check
	patterns := fs.Args()

	issues, err := c.CheckPackages(patterns, tags)
	if err != nil {
		return err
	}

	for _, issue := range issues {
		fmt.Println(issue)
	}

	if len(issues) > 0 {
		os.Exit(1)
	}

	return nil
}

func parsePkgList(s string) []string {
	var result []string
	for _, part := range splitComma(s) {
		if part = trimSpace(part); part != "" {
			result = append(result, part)
		}
	}
	return result
}

func splitComma(s string) []string {
	// Handle both commas and spaces
	var result []string
	var current string
	for _, ch := range s {
		if ch == ',' || ch == ' ' {
			if current != "" {
				result = append(result, current)
				current = ""
			}
		} else {
			current += string(ch)
		}
	}
	if current != "" {
		result = append(result, current)
	}
	return result
}

func trimSpace(s string) string {
	result := ""
	for _, ch := range s {
		if ch != ' ' && ch != '\t' && ch != '\n' && ch != '\r' {
			result += string(ch)
		}
	}
	return result
}

type tagsFlag map[string]bool

func (t tagsFlag) String() string {
	return ""
}

func (t tagsFlag) Set(value string) error {
	for _, tag := range splitComma(value) {
		tag = trimSpace(tag)
		if tag != "" {
			t[tag] = true
		}
	}
	return nil
}

type ignoreFlag map[string]string

func (i ignoreFlag) String() string {
	return ""
}

func (i ignoreFlag) Set(value string) error {
	parts := splitComma(value)
	for _, part := range parts {
		part = trimSpace(part)
		if part == "" {
			continue
		}

		colonIdx := -1
		for idx, ch := range part {
			if ch == ':' {
				colonIdx = idx
				break
			}
		}

		if colonIdx == -1 {
			// No colon, apply to all packages
			i[""] = part
		} else {
			pkg := part[:colonIdx]
			pattern := part[colonIdx+1:]
			i[pkg] = pattern
		}
	}
	return nil
}
