package main

import (
	"flag"
	"fmt"
	"os"
)

func main() {
	if err := run(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(2)
	}
}

func run(args []string) error {
	fs := flag.NewFlagSet("errcheck", flag.ContinueOnError)
	fs.Usage = func() {}

	var (
		tags           tagsFlag
		ignore         ignoreFlag
		ignorepkg      string
		exclude        string
		ignoretests    = fs.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
		ignoregenerated = fs.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
		blank          = fs.Bool("blank", false, "if true, check for errors assigned to blank identifier")
		asserts        = fs.Bool("asserts", false, "if true, check for ignored type assertion results")
		abspath        = fs.Bool("abspath", false, "print absolute paths to files")
		verbose        = fs.Bool("verbose", false, "produce more verbose logging")
		excludeonly    = fs.Bool("excludeonly", false, "Use only excludes from -exclude file")
		mod            string
	)

	fs.Var(&tags, "tags", "comma or space-separated list of build tags to include")
	fs.Var(&ignore, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	fs.StringVar(&ignorepkg, "ignorepkg", "", "comma-separated list of package paths to ignore")
	fs.StringVar(&exclude, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	fs.StringVar(&mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")

	err := fs.Parse(args)
	if err != nil {
		if err == flag.ErrHelp {
			fs.PrintDefaults()
			return nil
		}
		fs.PrintDefaults()
		return err
	}

	if fs.NArg() == 0 {
		return nil
	}

	c := NewChecker(
		*ignoretests,
		*ignoregenerated,
		*blank,
		*asserts,
		*abspath,
		*verbose,
		*excludeonly,
	)

	// Add ignore patterns
	for pkg, pattern := range ignore {
		if err := c.AddIgnorePattern(pkg, pattern); err != nil {
			return fmt.Errorf("failed to compile ignore pattern for %s: %v", pkg, err)
		}
	}

	// Add ignore packages
	if ignorepkg != "" {
		for _, pkg := range parsePkgList(ignorepkg) {
			c.AddIgnorePackage(pkg)
		}
	}

	// Load excludes from file
	if exclude != "" {
		if err := c.LoadExcludes(exclude); err != nil {
			return fmt.Errorf("failed to load excludes: %v", err)
		}
	}

	// Set module mode
	if mod != "" {
		os.Setenv("GOFLAGS", fmt.Sprintf("-mod=%s", mod))
	}

	// Get packages to check
	patterns := fs.Args()

	issues, err := c.CheckPackages(patterns, tags)
	if err != nil {
		return err
	}

	for _, issue := range issues {
		fmt.Println(issue)
	}

	if len(issues) > 0 {
		os.Exit(1)
	}

	return nil
}

func parsePkgList(s string) []string {
	var result []string
	for _, part := range splitComma(s) {
		if part = trimSpace(part); part != "" {
			result = append(result, part)
		}
	}
	return result
}

func splitComma(s string) []string {
	// Handle both commas and spaces
	var result []string
	var current string
	for _, ch := range s {
		if ch == ',' || ch == ' ' {
			if current != "" {
				result = append(result, current)
				current = ""
			}
		} else {
			current += string(ch)
		}
	}
	if current != "" {
		result = append(result, current)
	}
	return result
}

func trimSpace(s string) string {
	result := ""
	for _, ch := range s {
		if ch != ' ' && ch != '\t' && ch != '\n' && ch != '\r' {
			result += string(ch)
		}
	}
	return result
