		Importer: importer.Default(),
	}
	info := &types.Info{
		Types:      make(map[ast.Expr]types.TypeAndValue),
		Defs:       make(map[*ast.Ident]types.Object),
		Uses:       make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
	}

	_, err = tc.Check("main", fset, []*ast.File{file}, info)
	fmt.Printf("Type check error: %v\n", err)
	fmt.Printf("Types collected: %d\n", len(info.Types))

	// Find the call
	for expr, typeVal := range info.Types {
		fmt.Printf("Expr: %T, Type: %v\n", expr, typeVal.Type)
	}
}

