}

func (v *fileVisitor) isErrorReturningCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	return v.hasErrorReturn(call)
}

func (v *fileVisitor) hasErrorReturn(call *ast.CallExpr) bool {
	// Get the function type from type info
	callType := v.info.TypeOf(call.Fun)
	if callType == nil {
		return false
	}

	var sig *types.Signature
	switch t := callType.(type) {
	case *types.Signature:
		sig = t
	case *types.Named:
		if s, ok := t.Underlying().(*types.Signature); ok {
			sig = s
		}
	}

	if sig == nil || sig.Results() == nil || sig.Results().Len() == 0 {
		return false
	}

	// Check if last return type is error
	lastResult := sig.Results().At(sig.Results().Len() - 1)
	return isErrorType(lastResult.Type())
}

func isErrorType(t types.Type) bool {
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Pkg() == nil && named.Obj().Name() == "error"
	}
	return false
}

func (v *fileVisitor) isIgnored(funcName string) bool {
	checker := v.checker

	// Check if in exclude list
	if checker.exclude[funcName] {
		return true
	}

	// Check if excluded via standard excludes (unless excludeonly)
	if !checker.excludeOnly && checker.stdExcludes[funcName] {
		return true
	}

	// Check package ignore patterns
	parts := strings.Split(funcName, ".")
	if len(parts) > 0 {
		pkg := parts[0]
		if checker.ignorePackages[pkg] {
			return true
		}

		if rx, ok := checker.ignoreRx[pkg]; ok {
			if rx.MatchString(funcName) {
				return true
			}
		}

		// Also check default ignore patterns
		if !checker.excludeOnly {
			if rx, ok := checker.ignoreRx[""]; ok {
				if rx.MatchString(funcName) {
					return true
				}
			}
		}
	}

	return false
}

func (v *fileVisitor) getFuncName(expr ast.Expr) string {
	switch n := expr.(type) {
	case *ast.SelectorExpr:
		return v.getFuncName(n.X) + "." + n.Sel.Name
	case *ast.Ident:
		return n.Name
	default:
		return "unknown"
	}
}

func (v *fileVisitor) getCallString(expr ast.Expr) string {
	switch n := expr.(type) {
	case *ast.CallExpr:
		return v.getFuncName(n.Fun)
	case *ast.SelectorExpr:
		return v.getFuncName(n.X) + "." + n.Sel.Name
	case *ast.Ident:
		return n.Name
	default:
		return "unknown"
	}
}

func (v *fileVisitor) formatIssue(pos token.Pos, funcName, callStr string) string {
	posInfo := v.fset.Position(pos)
	filename := posInfo.Filename

	if !v.checker.abspath {
		if rel, err := filepath.Rel(".", filename); err == nil {
			filename = rel
		}
	}

	return fmt.Sprintf("%s:%d:%d:\t%s(%s)", filename, posInfo.Line, posInfo.Column, funcName, callStr)
}

func isGeneratedFile(file *ast.File) bool {
	for _, commentGroup := range file.Comments {
		for _, comment := range commentGroup.List {
			text := comment.Text
			if strings.Contains(text, "Code generated") && strings.Contains(text, "DO NOT EDIT") {
				return true
			}
		}
	}
	return false
}
