package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/token"
	"go/types"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type Checker struct {
	ignoreTests      bool
	ignoreGenerated  bool
	ignoreRx         map[string]*regexp.Regexp
	ignorePackages   map[string]bool
	blank            bool
	asserts          bool
	abspath          bool
	verbose          bool
	exclude          map[string]bool
	excludeOnly      bool
	stdExcludes      map[string]bool
}

func NewChecker(ignoreTests, ignoreGenerated, blank, asserts, abspath, verbose, excludeOnly bool) *Checker {
	return &Checker{
		ignoreTests:     ignoreTests,
		ignoreGenerated: ignoreGenerated,
		blank:           blank,
		asserts:         asserts,
		abspath:         abspath,
		verbose:         verbose,
		exclude:         make(map[string]bool),
		excludeOnly:     excludeOnly,
		ignoreRx:        make(map[string]*regexp.Regexp),
		ignorePackages:  make(map[string]bool),
		stdExcludes:     getStdExcludes(),
	}
}

func getStdExcludes() map[string]bool {
	return map[string]bool{
		"fmt.Print":        true,
		"fmt.Println":      true,
		"fmt.Printf":       true,
		"fmt.Fprint":       true,
		"fmt.Fprintln":     true,
		"fmt.Fprintf":      true,
		"fmt.Sprint":       true,
		"fmt.Sprintln":     true,
		"fmt.Sprintf":      true,
	}
}

func (c *Checker) AddIgnorePattern(pkg string, pattern string) error {
	rx, err := regexp.Compile(pattern)
	if err != nil {
		return err
	}
	c.ignoreRx[pkg] = rx
	return nil
}

func (c *Checker) AddIgnorePackage(pkg string) {
	c.ignorePackages[pkg] = true
}

func (c *Checker) AddExclude(name string) {
	c.exclude[name] = true
}

func (c *Checker) LoadExcludes(filename string) error {
	file, err := os.Open(filename)
	if err != nil {
		return err
	}
	defer file.Close()

	scanner := bufio.NewScanner(file)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		c.AddExclude(line)
	}
	return scanner.Err()
}

func (c *Checker) CheckPackages(patterns []string, tags map[string]bool) ([]string, error) {
	var issues []string

	for _, pattern := range patterns {
		pkgIssues, err := c.checkPattern(pattern)
		if err != nil {
			return nil, err
		}
		issues = append(issues, pkgIssues...)
	}

	sort.Strings(issues)
	return issues, nil
}

func (c *Checker) checkPattern(pattern string) ([]string, error) {
	var issues []string

	if strings.HasSuffix(pattern, "/...") {
		basePattern := strings.TrimSuffix(pattern, "/...")
		if err := filepath.WalkDir(basePattern, func(dirPath string, entry fs.DirEntry, err error) error {
			if err != nil {
				return nil
			}
			if !entry.IsDir() {
				return nil
			}

			name := entry.Name()
			if strings.HasPrefix(name, ".") || name == "vendor" {
				return filepath.SkipDir
			}

			pkgIssues, err := c.checkDir(dirPath)
			if err != nil {
				return err
			}
			issues = append(issues, pkgIssues...)
			return nil
		}); err != nil {
			return nil, err
		}
	} else {
		pkgIssues, err := c.checkDir(pattern)
		if err != nil {
			return nil, fmt.Errorf("errors while loading package %s: %v", pattern, err)
		}
		issues = append(issues, pkgIssues...)
	}

	return issues, nil
}

func (c *Checker) checkDir(dir string) ([]string, error) {
	var issues []string

	fset := token.NewFileSet()
	pkgs, err := parser.ParseDir(fset, dir, c.filenameFilter, parser.AllErrors)

	if err != nil {
		return nil, err
	}

	if len(pkgs) == 0 {
		return nil, nil
	}

	for pkgName, pkg := range pkgs {
		if c.verbose {
			fmt.Printf("checking %s\n", pkgName)
		}

		var files []*ast.File
		for _, file := range pkg.Files {
			files = append(files, file)
		}

		tc := &types.Config{
			Importer: importer.Default(),
		}
		info := &types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Defs:       make(map[*ast.Ident]types.Object),
			Uses:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		}

		_, _ = tc.Check(pkg.Name, fset, files, info)

		for filename, file := range pkg.Files {
			if c.ignoreGenerated && isGeneratedFile(file) {
				continue
			}

			fileIssues := c.checkFile(file, fset, info, filename)
			issues = append(issues, fileIssues...)
		}
	}

	return issues, nil
}

func (c *Checker) filenameFilter(info fs.FileInfo) bool {
	name := info.Name()
	if c.ignoreTests && strings.HasSuffix(name, "_test.go") {
		return false
	}
	return strings.HasSuffix(name, ".go")
}

func (c *Checker) checkFile(file *ast.File, fset *token.FileSet, info *types.Info, filename string) []string {
	var issues []string

	visitor := &fileVisitor{
		checker:  c,
		fset:     fset,
		info:     info,
		filename: filename,
		issues:   &issues,
	}
	ast.Walk(visitor, file)

	return issues
}

type fileVisitor struct {
	checker  *Checker
	fset     *token.FileSet
	info     *types.Info
	filename string
	issues   *[]string
}

func (v *fileVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return v
	}

	switch n := node.(type) {
	case *ast.ExprStmt:
		v.checkExprStmt(n)
	case *ast.AssignStmt:
		v.checkAssignStmt(n)
	}

	return v
}

func (v *fileVisitor) checkExprStmt(stmt *ast.ExprStmt) {
	call, ok := stmt.X.(*ast.CallExpr)
	if !ok {
		return
	}

	funcName := v.getFuncName(call.Fun)
	if v.isIgnored(funcName) {
		return
	}

	if v.hasErrorReturn(call) {
		if v.checker.verbose {
			fmt.Printf("  %s\t%s\n", funcName, v.getCallString(stmt.X))
		}

		issue := v.formatIssue(stmt.Pos(), funcName, v.getCallString(stmt.X))
		*v.issues = append(*v.issues, issue)
	}
}

func (v *fileVisitor) checkAssignStmt(stmt *ast.AssignStmt) {
	if !v.checker.blank || stmt.Tok != token.ASSIGN {
		return
	}

	for i, lhs := range stmt.Lhs {
		if ident, ok := lhs.(*ast.Ident); ok && ident.Name == "_" {
			if i < len(stmt.Rhs) {
				if v.isErrorReturningCall(stmt.Rhs[i]) {
					issue := v.formatIssue(stmt.Pos(), v.getFuncName(stmt.Rhs[i]), v.getCallString(stmt.Rhs[i]))
					*v.issues = append(*v.issues, issue)
				}
			}
		}
	}
}

func (v *fileVisitor) isErrorReturningCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	return v.hasErrorReturn(call)
}

func (v *fileVisitor) hasErrorReturn(call *ast.CallExpr) bool {
	funType := v.info.TypeOf(call.Fun)
	if funType == nil {
		return false
	}

	var sig *types.Signature
	switch t := funType.(type) {
	case *types.Signature:
		sig = t
	case *types.Named:
		if s, ok := t.Underlying().(*types.Signature); ok {
			sig = s
		}
	}

	if sig == nil || sig.Results() == nil || sig.Results().Len() == 0 {
		return false
	}

	lastResult := sig.Results().At(sig.Results().Len() - 1)
	return isErrorType(lastResult.Type())
}

func isErrorType(t types.Type) bool {
	if named, ok := t.(*types.Named); ok {
		return named.Obj().Pkg() == nil && named.Obj().Name() == "error"
	}
	return false
}

func (v *fileVisitor) isIgnored(funcName string) bool {
	checker := v.checker

	if checker.exclude[funcName] {
		return true
	}

