	if err != nil {
		fmt.Printf("Parse error: %v\n", err)
		return
	}

	fmt.Printf("Packages: %d\n", len(pkgs))

	for pkgName, pkg := range pkgs {
		fmt.Printf("Package: %s\n", pkgName)

		var files []*ast.File
		for _, file := range pkg.Files {
			files = append(files, file)
		}

		tc := &types.Config{
			Importer: importer.Default(),
		}
		info := &types.Info{
			Types:      make(map[ast.Expr]types.TypeAndValue),
			Defs:       make(map[*ast.Ident]types.Object),
			Uses:       make(map[*ast.Ident]types.Object),
			Selections: make(map[*ast.SelectorExpr]*types.Selection),
		}

		_, _ = tc.Check(pkg.Name, fset, files, info)

		// Walk to find calls
		for _, file := range files {
			ast.Walk(&walkVisitor{info: info}, file)
		}
	}
}

type walkVisitor struct {
	info *types.Info
}

func (w *walkVisitor) Visit(node ast.Node) ast.Visitor {
	if node == nil {
		return w
	}

	if stmt, ok := node.(*ast.ExprStmt); ok {
		if call, ok := stmt.X.(*ast.CallExpr); ok {
			funType := w.info.TypeOf(call.Fun)
			fmt.Printf("Found call with fun type: %v\n", funType)

			if sig, ok := funType.(*types.Signature); ok {
				if sig.Results() != nil && sig.Results().Len() > 0 {
					last := sig.Results().At(sig.Results().Len() - 1)
					if named, ok := last.Type().(*types.Named); ok {
						if named.Obj().Pkg() == nil && named.Obj().Name() == "error" {
							fmt.Printf("  -> HAS ERROR RETURN!\n")
						}
					}
				}
			}
		}
	}

	return w
}

func init() {
	test()
}
EOF
