cd /tmp && mkdir -p errcheck_edge_test && cd errcheck_edge_test && cat > main.go << 'EOF'
package main

import (
	"bytes"
	"io"
	"os"
)

func main() {
	// Test 1: Standard library functions that are typically ignored
	var buf bytes.Buffer
	buf.Write([]byte("test"))

	// Test 2: Functions with specific receivers
	io.Copy(os.Stdout, nil)

	// Test 3: Multiple errors on same line
	os.Create("a.txt"); os.Create("b.txt")
}
EOF
go mod init test
/workspace/executable ./... 2>&1 | head -10

