cd /tmp && mkdir -p final_check && cd final_check && cat > main.go << 'EOF'
package main

import (
	"fmt"
	"os"
)

func main() {
	// Unchecked error
	os.Create("file.txt")

	// Checked error (should not be reported)
	err := os.Remove("file.txt")
	if err != nil {
		fmt.Println("Error:", err)
	}

	// Standard library function (ignored by default)
	fmt.Println("done")
}
EOF

go mod init final_check

echo "=== Baseline test ==="
/workspace/executable ./... 2>&1

echo ""
echo "=== With excludeonly flag ==="
/workspace/executable -excludeonly ./... 2>&1 | head -5

